/** Weekday labels (MM-DD) from 2026-08-03; 2026-09-24/25 (추석 연휴) are kept as gap days. */
function tradingDays(n: number): { dates: string[]; closed: Set<number> } {
  const dates: string[] = [];
  const closed = new Set<number>();
  const d = new Date(Date.UTC(2026, 7, 3));
  while (dates.length < n) {
    const wd = d.getUTCDay();
    if (wd !== 0 && wd !== 6) {
      const md = `${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
      if (md === '09-24' || md === '09-25') closed.add(dates.length);
      dates.push(md);
    }
    d.setUTCDate(d.getUTCDate() + 1);
  }
  return { dates, closed };
}

const r50 = (x: number): number => Math.round(x / 50) * 50;
const closeAt = (i: number): number => r50(50000 + 4000 * Math.sin(i / 7) + 60 * i + 1500 * Math.sin(i / 2.3));

function series(n: number) {
  const { dates, closed } = tradingDays(n);
  const ohlc = dates.map((_, i) => {
    if (closed.has(i)) return null;
    const close = closeAt(i);
    const open = r50((i ? closeAt(i - 1) : close) + 300 * Math.sin(i * 1.7));
    const high = r50(Math.max(open, close) + 200 + 150 * Math.abs(Math.sin(i * 0.9)));
    const low = r50(Math.min(open, close) - 200 - 120 * Math.abs(Math.cos(i * 1.3)));
    return { open, high, low, close };
  });
  const volume = dates.map((_, i) => (closed.has(i) ? null : Math.round((1.2e6 + 4e5 * Math.sin(i / 3) + 3e5 * Math.abs(Math.cos(i * 0.7))) / 1000) * 1000));
  return { dates, ohlc, close: ohlc.map((d) => (d ? d.close : null)), volume };
}

